export function extendDailyCapacity(items){
 const topics=new Set(items.map(q=>q.topicId));
 const ids=new Set(items.map(q=>q.id));
 return [...items,...dailySupplement.filter(q=>topics.has(q.topicId)&&!ids.has(q.id))];
}
